css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .pos-tabla{border-collapse: collapse;}
.mz .pos-tabla th,.mz .pos-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .pos-tabla th{font-family: sans-serif; font-size: 11.5px; background: #f3f3f3; padding: 3px 0; width: 80px;}
.mz .pos-tabla td{height: 32px; font-size: 19px; font-weight: 700;}
.mz .pos-tabla td.pos-dado{background: #f3f3f3; width: 90px;}
.mz .desc-fila{display: flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 700; margin-bottom: 8px; flex-wrap: wrap;}
.mz .desc-fila .num-grande{min-width: 56px;}
.mz .desc-fila .caja-sum{width: 70px; height: 32px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .desc-fila .mas{font-family: sans-serif;}
.mz .equiv-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 7px 30px;}
.mz .equiv-fila{display: flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 700;}
.mz .equiv-fila .pieza{white-space: nowrap;}
.mz .equiv-fila .caja-eq{width: 50px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .vf-fila{display: flex; align-items: center; gap: 12px; font-size: 14.5px; font-weight: 600; margin-bottom: 8px;}
.mz .vf-fila .frase{flex: 1; line-height: 1.3;}
.mz .vf-opts{display: flex; gap: 10px; flex-shrink: 0;}
.mz .vf-opts .vf{width: 30px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 15px;}
